# Solve the current peg-solitaire layout by DFS.
pegs={(38,25),(50,25),(50,31),(44,37),(50,37),(44,43)}
valid={(32+6*c,19+6*r) for r in range(6) for c in range(4)}-{(50,19)}
def moves(s):
 for x,y in sorted(s):
  for dx,dy in [(12,0),(-12,0),(0,12),(0,-12)]:
   m=(x+dx//2,y+dy//2); d=(x+dx,y+dy)
   if m in s and d in valid and d not in s:
    yield (x,y),d,(s-{(x,y),m})|{d}
seen=set()
def dfs(s,path):
 if len(s)==1:return path
 k=frozenset(s)
 if k in seen:return None
 seen.add(k)
 for a,b,t in moves(s):
  z=dfs(t,path+[(a,b)])
  if z is not None:return z
 return None
sol=dfs(pegs,[])
print(sol)

